fn inTable(cp: u21) bool {
    return (cp >= 0x2E80 and cp <= 0x2FFF) or
        (cp >= 0xF900 and cp <= 0xFAFF) or
        (cp >= 0xFB00 and cp <= 0xFB4F) or
        (cp >= 0xFF10 and cp <= 0xFF19) or
        (cp >= 0xFF21 and cp <= 0xFF3A) or
        (cp >= 0xFF41 and cp <= 0xFF5A);
}

/// NFKC / radical replacement for a codepoint, if one is needed.
pub fn lookup(cp: u21) ?*const Entry {
    if (!inTable(cp)) return null;
    var lo: usize = 0;
    var hi: usize = entries.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = &entries[mid];
        if (e.cp == cp) return e;
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return null;
}

/// Characters that never carry printable meaning in extracted text.
pub fn ignorable(cp: u21) bool {
    switch (cp) {
        0x0000,
        0x0001,
        0x0002,
        0x0003,
        0x0004,
        0x0005,
        0x0006,
        0x0007,
        0x0008,
        0x000B,
        0x000C,
        0x000E,
        0x000F,
        0x0010,
        0x0011,
        0x0012,
        0x0013,
        0x0014,
        0x0015,
        0x0016,
        0x0017,
        0x0018,
        0x0019,
        0x001A,
        0x001B,
        0x001C,
        0x001D,
        0x001E,
        0x001F,
        0x00AD,
        0x200B,
        0x200C,
        0x200D,
        0x200E,
        0x200F,
        0x202A,
        0x202B,
        0x202C,
        0x202D,
        0x202E,
        0x2060,
        0x2061,
        0x2062,
        0x2063,
        0x2064,
        0xFEFF,
        0xFFFD,
        0xFFFE,
        0xFFFF,
        => return true,
        else => return false,
    }
}
